package com.userd40.nozeros;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("nozeros")
public interface NoZerosConfig extends Config
{
	@ConfigItem(keyName = "hideNpc", name = "Hide on NPCs", description = "")
	default boolean hideNpc()
	{
		return true;
	}

	@ConfigItem(keyName = "hidePlayer", name = "Hide on my player", description = "")
	default boolean hidePlayer()
	{
		return true;
	}

	@ConfigItem(keyName = "hideOtherPlayer", name = "Hide on other players", description = "")
	default boolean hideOtherPlayer()
	{
		return true;
	}
}

package com.userd40.nozeros;

import java.nio.charset.Charset;
import net.runelite.api.Client;
import net.runelite.api.HitsplatID;
import net.runelite.api.gameval.SpriteID;

final class NoZerosHitmark
{
	static final int TRANSFORM_UNAVAILABLE = Integer.MIN_VALUE;

	private static final int HITMARK_CONFIG_ARCHIVE = 32;
	private static final Charset CP1252 = Charset.forName("windows-1252");

	private final int firstSpriteId;
	private final int middleSpriteId;
	private final int secondSpriteId;
	private final int lastSpriteId;
	private final int textColor;
	private final String textTemplate;
	private final int duration;
	private final int textYOffset;
	private final int transformVarbit;
	private final int transformVarp;
	private final int[] transforms;
	private final boolean fallbackDefinition;

	private NoZerosHitmark(
		int firstSpriteId,
		int middleSpriteId,
		int secondSpriteId,
		int lastSpriteId,
		int textColor,
		String textTemplate,
		int duration,
		int textYOffset,
		int transformVarbit,
		int transformVarp,
		int[] transforms,
		boolean fallbackDefinition)
	{
		this.firstSpriteId = firstSpriteId;
		this.middleSpriteId = middleSpriteId;
		this.secondSpriteId = secondSpriteId;
		this.lastSpriteId = lastSpriteId;
		this.textColor = textColor;
		this.textTemplate = textTemplate;
		this.duration = duration;
		this.textYOffset = textYOffset;
		this.transformVarbit = transformVarbit;
		this.transformVarp = transformVarp;
		this.transforms = transforms;
		this.fallbackDefinition = fallbackDefinition;
	}

	static NoZerosHitmark load(Client client, int hitsplatType)
	{
		try
		{
			byte[] data = client.getIndexConfig().loadData(HITMARK_CONFIG_ARCHIVE, hitsplatType);
			return decode(data, hitsplatType);
		}
		catch (RuntimeException ex)
		{
			return fallback(hitsplatType);
		}
	}

	static NoZerosHitmark decode(byte[] data, int hitsplatType)
	{
		if (data == null)
		{
			return fallback(hitsplatType);
		}

		DecodedDefinition decoded = new DecodedDefinition();
		Buffer buffer = new Buffer(data);
		while (true)
		{
			int opcode = buffer.readUnsignedByte();
			if (opcode == 0)
			{
				return decoded.toDefinition();
			}

			decoded.decodeNext(buffer, opcode);
		}
	}

	boolean hasTransforms()
	{
		return transforms != null;
	}

	boolean hasRenderableContent()
	{
		return firstSpriteId >= 0
			|| middleSpriteId >= 0
			|| secondSpriteId >= 0
			|| lastSpriteId >= 0
			|| !textTemplate.isEmpty();
	}

	boolean isFallbackDefinition()
	{
		return fallbackDefinition;
	}

	int getTransformedType(Client client)
	{
		if (transforms == null)
		{
			return -1;
		}

		int selector = -1;
		try
		{
			if (transformVarbit != -1)
			{
				selector = client.getVarbitValue(transformVarbit);
			}
			else if (transformVarp != -1)
			{
				selector = client.getVarpValue(transformVarp);
			}
		}
		catch (RuntimeException ex)
		{
			return TRANSFORM_UNAVAILABLE;
		}

		return getTransformedTypeForSelector(selector);
	}

	int getTransformedTypeForSelector(int selector)
	{
		if (transforms == null)
		{
			return -1;
		}

		int index = selector >= 0 && selector < transforms.length - 1
			? selector
			: transforms.length - 1;
		return transforms[index];
	}

	String formatAmount(int amount)
	{
		String formatted = textTemplate;
		while (true)
		{
			int index = formatted.indexOf("%1");
			if (index < 0)
			{
				return formatted;
			}

			formatted = formatted.substring(0, index) + amount + formatted.substring(index + 2);
		}
	}

	int getFirstSpriteId()
	{
		return firstSpriteId;
	}

	int getMiddleSpriteId()
	{
		return middleSpriteId;
	}

	int getSecondSpriteId()
	{
		return secondSpriteId;
	}

	int getLastSpriteId()
	{
		return lastSpriteId;
	}

	int getTextColor()
	{
		return textColor;
	}

	int getDuration()
	{
		return duration;
	}

	int appearanceGameCycle(int disappearsOnGameCycle)
	{
		return disappearsOnGameCycle - duration;
	}

	int getTextYOffset()
	{
		return textYOffset;
	}

	private static NoZerosHitmark fallback(int hitsplatType)
	{
		return new NoZerosHitmark(
			fallbackSpriteId(hitsplatType),
			-1,
			-1,
			-1,
			0xFFFFFF,
			"%1",
			70,
			0,
			-1,
			-1,
			null,
			true);
	}

	private static int fallbackSpriteId(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.POISON:
				return SpriteID.Hitmark.HITSPLAT_GREEN_POISON;
			case HitsplatID.VENOM:
				return SpriteID.Hitmark.HITSPLAT_DARK_GREEN_VENOM;
			default:
				return SpriteID.Hitmark.HITSPLAT_BLUE_MISS;
		}
	}

	private static final class DecodedDefinition
	{
		private int firstSpriteId = -1;
		private int middleSpriteId = -1;
		private int secondSpriteId = -1;
		private int lastSpriteId = -1;
		private int textColor = 0xFFFFFF;
		private String textTemplate = "";
		private int duration = 70;
		private int textYOffset;
		private int transformVarbit = -1;
		private int transformVarp = -1;
		private int[] transforms;

		private void decodeNext(Buffer buffer, int opcode)
		{
			switch (opcode)
			{
				case 1:
					buffer.readNullableLargeSmart();
					break;
				case 2:
					textColor = buffer.readMedium();
					break;
				case 3:
					firstSpriteId = buffer.readNullableLargeSmart();
					break;
				case 4:
					secondSpriteId = buffer.readNullableLargeSmart();
					break;
				case 5:
					middleSpriteId = buffer.readNullableLargeSmart();
					break;
				case 6:
					lastSpriteId = buffer.readNullableLargeSmart();
					break;
				case 7:
					buffer.readShort();
					break;
				case 8:
					textTemplate = buffer.readStringCp1252NullCircumfixed();
					break;
				case 9:
					duration = buffer.readUnsignedShort();
					break;
				case 10:
					buffer.readShort();
					break;
				case 11:
					break;
				case 12:
					buffer.readUnsignedByte();
					break;
				case 13:
					textYOffset = buffer.readShort();
					break;
				case 14:
					buffer.readUnsignedShort();
					break;
				case 15:
				case 16:
					break;
				case 17:
				case 18:
					decodeTransforms(buffer, opcode == 18);
					break;
				default:
					throw new IllegalArgumentException("Unknown hitmark opcode " + opcode);
			}
		}

		private void decodeTransforms(Buffer buffer, boolean hasFallback)
		{
			transformVarbit = normalizeUnsignedShort(buffer.readUnsignedShort());
			transformVarp = normalizeUnsignedShort(buffer.readUnsignedShort());
			int fallbackTransform = -1;
			if (hasFallback)
			{
				fallbackTransform = normalizeUnsignedShort(buffer.readUnsignedShort());
			}

			int count = buffer.readUnsignedByte();
			transforms = new int[count + 2];
			for (int i = 0; i <= count; i++)
			{
				transforms[i] = normalizeUnsignedShort(buffer.readUnsignedShort());
			}
			transforms[count + 1] = fallbackTransform;
		}

		private NoZerosHitmark toDefinition()
		{
			return new NoZerosHitmark(
				firstSpriteId,
				middleSpriteId,
				secondSpriteId,
				lastSpriteId,
				textColor,
				textTemplate,
				duration,
				textYOffset,
				transformVarbit,
				transformVarp,
				transforms,
				false);
		}

		private static int normalizeUnsignedShort(int value)
		{
			return value == 65535 ? -1 : value;
		}
	}

	private static final class Buffer
	{
		private final byte[] data;
		private int offset;

		private Buffer(byte[] data)
		{
			this.data = data;
		}

		private int readUnsignedByte()
		{
			return data[offset++] & 0xFF;
		}

		private int readUnsignedShort()
		{
			offset += 2;
			return ((data[offset - 2] & 0xFF) << 8) | (data[offset - 1] & 0xFF);
		}

		private int readShort()
		{
			int value = readUnsignedShort();
			return value > 32767 ? value - 65536 : value;
		}

		private int readMedium()
		{
			offset += 3;
			return ((data[offset - 3] & 0xFF) << 16)
				| ((data[offset - 2] & 0xFF) << 8)
				| (data[offset - 1] & 0xFF);
		}

		private int readInt()
		{
			offset += 4;
			return ((data[offset - 4] & 0xFF) << 24)
				| ((data[offset - 3] & 0xFF) << 16)
				| ((data[offset - 2] & 0xFF) << 8)
				| (data[offset - 1] & 0xFF);
		}

		private int readNullableLargeSmart()
		{
			if (data[offset] < 0)
			{
				return readInt() & Integer.MAX_VALUE;
			}

			int value = readUnsignedShort();
			return value == 32767 ? -1 : value;
		}

		private String readStringCp1252NullCircumfixed()
		{
			if (readUnsignedByte() != 0)
			{
				throw new IllegalStateException("Expected circumfixed string prefix");
			}

			int start = offset;
			while (data[offset++] != 0)
			{
				continue;
			}

			int length = offset - start - 1;
			return length == 0 ? "" : new String(data, start, length, CP1252);
		}
	}
}

package com.userd40.nozeros;

final class NoZerosHitsplat
{
	private final int type;
	private final int amount;
	private final boolean mine;
	private final boolean hidden;
	private final int position;
	private final int appearedCycle;
	private final int expiresCycle;
	private final long sequence;

	NoZerosHitsplat(
		int type,
		int amount,
		boolean mine,
		boolean hidden,
		int position,
		int appearedCycle,
		int expiresCycle,
		long sequence)
	{
		this.type = type;
		this.amount = amount;
		this.mine = mine;
		this.hidden = hidden;
		this.position = position;
		this.appearedCycle = appearedCycle;
		this.expiresCycle = expiresCycle;
		this.sequence = sequence;
	}

	int getType()
	{
		return type;
	}

	int getAmount()
	{
		return amount;
	}

	boolean isMine()
	{
		return mine;
	}

	boolean isHidden()
	{
		return hidden;
	}

	int getPosition()
	{
		return position;
	}

	long getSequence()
	{
		return sequence;
	}

	boolean isVisibleAt(int gameCycle)
	{
		return gameCycle >= appearedCycle && gameCycle < expiresCycle;
	}

	boolean isExpired(int gameCycle)
	{
		return gameCycle >= expiresCycle;
	}
}

package com.userd40.nozeros;

import java.awt.FontMetrics;

final class NoZerosLayout
{
	private static final int DEFAULT_HEIGHT = 20;
	private static final double[][] CLOCKWISE_DIRECTIONS = {
		{1.0, 0.5},
		{0.0, 1.0},
		{-1.0, 0.5},
		{-1.0, -0.5},
		{0.0, -1.0},
		{1.0, -0.5}
	};

	private final int firstX;
	private final int secondX;
	private final int middleX;
	private final int lastX;
	private final int spriteY;
	private final int textX;
	private final int textBaseline;
	private final int middleRepeatCount;
	private final int width;
	private final int height;

	private NoZerosLayout(
		int firstX,
		int secondX,
		int middleX,
		int lastX,
		int spriteY,
		int textX,
		int textBaseline,
		int middleRepeatCount,
		int width,
		int height)
	{
		this.firstX = firstX;
		this.secondX = secondX;
		this.middleX = middleX;
		this.lastX = lastX;
		this.spriteY = spriteY;
		this.textX = textX;
		this.textBaseline = textBaseline;
		this.middleRepeatCount = middleRepeatCount;
		this.width = width;
		this.height = height;
	}

	static NoZerosLayout create(
		NoZerosSprite first,
		NoZerosSprite middle,
		NoZerosSprite second,
		NoZerosSprite last,
		String text,
		FontMetrics metrics,
		int textYOffset)
	{
		int textWidth = metrics.stringWidth(text);
		int firstWidth = width(first);
		int middleWidth = width(middle);
		int secondWidth = width(second);

		int repeatCount = 0;
		if (middleWidth > 0)
		{
			repeatCount = second == null && last == null ? 1 : textWidth / middleWidth + 1;
		}

		int cursorX = 0;
		int firstX = cursorX - offsetX(first);
		cursorX += firstWidth + 2;

		int secondX = cursorX - offsetX(second);
		cursorX += secondWidth;

		int middleX = cursorX - offsetX(middle);
		int textX = cursorX;
		if (middleWidth > 0)
		{
			int repeatedWidth = repeatCount * middleWidth;
			cursorX += repeatedWidth;
			textX += (repeatedWidth - textWidth) / 2;
		}
		else
		{
			cursorX += textWidth;
		}

		int lastX = cursorX - offsetX(last);
		boolean textOnly = first == null && middle == null && second == null && last == null;
		int textBaseline = textOnly
			? textYOffset + (DEFAULT_HEIGHT - metrics.getHeight()) / 2 + metrics.getAscent()
			: textYOffset + 15;

		Bounds bounds = new Bounds();
		bounds.include(first, firstX, 0);
		bounds.include(second, secondX, 0);
		for (int i = 0; i < repeatCount; i++)
		{
			bounds.include(middle, middleX + i * middleWidth, 0);
		}
		bounds.include(last, lastX, 0);
		if (!text.isEmpty())
		{
			bounds.include(
				textX,
				textBaseline - metrics.getAscent(),
				textX + Math.max(1, textWidth) + 1,
				textBaseline + metrics.getDescent() + 1);
		}

		if (!bounds.isInitialized())
		{
			bounds.include(0, 0, 1, DEFAULT_HEIGHT);
		}

		int translateX = -Math.floorDiv(bounds.minX + bounds.maxX, 2);
		int translateY = textOnly
			? -DEFAULT_HEIGHT / 2
			: -Math.floorDiv(bounds.minY + bounds.maxY, 2);

		return new NoZerosLayout(
			firstX + translateX,
			secondX + translateX,
			middleX + translateX,
			lastX + translateX,
			translateY,
			textX + translateX,
			textBaseline + translateY,
			repeatCount,
			bounds.maxX - bounds.minX,
			bounds.maxY - bounds.minY);
	}

	static int[] slotOffset(int position, int slotWidth, int slotHeight, int edgeCut)
	{
		if (position <= 0)
		{
			return new int[]{0, 0};
		}

		int indexOnRing = position - 1;
		int radius = 1;
		while (indexOnRing >= radius * 6)
		{
			indexOnRing -= radius * 6;
			radius++;
		}

		double sideSpacing = slotWidth - edgeCut;
		double verticalSpacing = slotHeight;
		double x = 0;
		double y = -verticalSpacing * radius;
		int remaining = indexOnRing;

		for (int side = 0; side < CLOCKWISE_DIRECTIONS.length && remaining > 0; side++)
		{
			int steps = Math.min(remaining, radius);
			x += CLOCKWISE_DIRECTIONS[side][0] * sideSpacing * steps;
			y += CLOCKWISE_DIRECTIONS[side][1] * verticalSpacing * steps;
			remaining -= steps;
		}

		return new int[]{(int) Math.round(x), (int) Math.round(y)};
	}

	int getFirstX()
	{
		return firstX;
	}

	int getSecondX()
	{
		return secondX;
	}

	int getMiddleX()
	{
		return middleX;
	}

	int getLastX()
	{
		return lastX;
	}

	int getSpriteY()
	{
		return spriteY;
	}

	int getTextX()
	{
		return textX;
	}

	int getTextBaseline()
	{
		return textBaseline;
	}

	int getMiddleRepeatCount()
	{
		return middleRepeatCount;
	}

	int getWidth()
	{
		return width;
	}

	int getHeight()
	{
		return height;
	}

	private static int width(NoZerosSprite sprite)
	{
		return sprite == null ? 0 : sprite.getWidth();
	}

	private static int offsetX(NoZerosSprite sprite)
	{
		return sprite == null ? 0 : sprite.getOffsetX();
	}

	private static final class Bounds
	{
		private int minX;
		private int minY;
		private int maxX;
		private int maxY;
		private boolean initialized;

		private void include(NoZerosSprite sprite, int x, int y)
		{
			if (sprite == null)
			{
				return;
			}

			int left = x + sprite.getOffsetX();
			int top = y + sprite.getOffsetY();
			include(left, top, left + sprite.getWidth(), top + sprite.getHeight());
		}

		private void include(int left, int top, int right, int bottom)
		{
			if (!initialized)
			{
				minX = left;
				minY = top;
				maxX = right;
				maxY = bottom;
				initialized = true;
				return;
			}

			minX = Math.min(minX, left);
			minY = Math.min(minY, top);
			maxX = Math.max(maxX, right);
			maxY = Math.max(maxY, bottom);
		}

		private boolean isInitialized()
		{
			return initialized;
		}
	}
}

package com.userd40.nozeros;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.HeadIcon;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class NoZerosOverlay extends Overlay
{
	private static final BufferedImage ANCHOR_IMAGE = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
	private static final int SLOT_WIDTH = 30;
	private static final int SLOT_HEIGHT = 20;
	private static final int SLOT_EDGE_CUT = 7;
	private static final int NO_OCCUPIED_TOP = Integer.MAX_VALUE;
	private static final int[][] STANDARD_HEALTH_SPRITES = {
		{30, SpriteID.StandardHealth30.FRONT, SpriteID.StandardHealth30.BACK},
		{40, SpriteID.StandardHealth40.FRONT, SpriteID.StandardHealth40.BACK},
		{50, SpriteID.StandardHealth50.FRONT, SpriteID.StandardHealth50.BACK},
		{60, SpriteID.StandardHealth60.FRONT, SpriteID.StandardHealth60.BACK},
		{70, SpriteID.StandardHealth70.FRONT, SpriteID.StandardHealth70.BACK},
		{80, SpriteID.StandardHealth80.FRONT, SpriteID.StandardHealth80.BACK},
		{90, SpriteID.StandardHealth90.FRONT, SpriteID.StandardHealth90.BACK},
		{100, SpriteID.StandardHealth100.FRONT, SpriteID.StandardHealth100.BACK},
		{120, SpriteID.StandardHealth120.FRONT, SpriteID.StandardHealth120.BACK},
		{140, SpriteID.StandardHealth140.FRONT, SpriteID.StandardHealth140.BACK},
		{160, SpriteID.StandardHealth160.FRONT, SpriteID.StandardHealth160.BACK}
	};
	private static final Comparator<NoZerosHitsplat> RENDER_ORDER = Comparator
		.comparing(NoZerosHitsplat::isMine)
		.thenComparingLong(NoZerosHitsplat::getSequence);

	private final Client client;
	private final NoZerosPlugin plugin;

	@Inject
	NoZerosOverlay(Client client, NoZerosPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Map<Actor, List<NoZerosHitsplat>> tracked = plugin.getHitsplats();
		if (tracked.isEmpty())
		{
			return null;
		}

		int gameCycle = client.getGameCycle();
		Graphics2D overlayGraphics = (Graphics2D) graphics.create();
		try
		{
			overlayGraphics.setFont(FontManager.getRunescapeSmallFont());
			overlayGraphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			overlayGraphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

			for (Map.Entry<Actor, List<NoZerosHitsplat>> entry : tracked.entrySet())
			{
				Actor actor = entry.getKey();
				if (!plugin.isSuppressed(actor))
				{
					continue;
				}

				int occupiedTopY = renderHealthBar(overlayGraphics, actor);
				renderHeadIcons(overlayGraphics, actor, occupiedTopY);
				renderHitsplats(overlayGraphics, actor, entry.getValue(), gameCycle);
			}
		}
		finally
		{
			overlayGraphics.dispose();
		}

		return null;
	}

	private int renderHealthBar(Graphics2D graphics, Actor actor)
	{
		int ratio = actor.getHealthRatio();
		int scale = actor.getHealthScale();
		if (ratio < 0 || scale <= 0)
		{
			return NO_OCCUPIED_TOP;
		}

		Point anchor = actor.getCanvasImageLocation(ANCHOR_IMAGE, actor.getLogicalHeight() + 15);
		if (anchor == null)
		{
			return NO_OCCUPIED_TOP;
		}

		int[] spriteIds = healthSpritesFor(scale);
		NoZerosSprite front = plugin.getSprite(spriteIds[1], 0);
		NoZerosSprite back = plugin.getSprite(spriteIds[2], 0);
		if (front == null || back == null)
		{
			return NO_OCCUPIED_TOP;
		}

		int width = back.getWidth();
		int height = back.getHeight();
		int x = anchor.getX() - width / 2;
		int y = anchor.getY() - height - 2;
		int fillWidth = filledWidth(width, ratio, scale);

		Graphics2D barGraphics = (Graphics2D) graphics.create();
		try
		{
			barGraphics.drawImage(back.getImage(), x, y, null);
			barGraphics.clipRect(x, y, fillWidth, height);
			barGraphics.drawImage(front.getImage(), x, y, null);
		}
		finally
		{
			barGraphics.dispose();
		}

		return y;
	}

	private int renderHeadIcons(Graphics2D graphics, Actor actor, int occupiedTopY)
	{
		List<NoZerosSprite> icons = new ArrayList<>(4);
		if (actor instanceof Player)
		{
			addPlayerIcons(icons, (Player) actor);
		}
		else if (actor instanceof NPC)
		{
			addNpcIcons(icons, (NPC) actor);
		}

		addHintArrow(icons, actor);
		if (icons.isEmpty())
		{
			return occupiedTopY;
		}

		Point anchor = actor.getCanvasImageLocation(ANCHOR_IMAGE, actor.getLogicalHeight() + 15);
		if (anchor == null)
		{
			return occupiedTopY;
		}

		int cursorBottomY = occupiedTopY == NO_OCCUPIED_TOP
			? anchor.getY()
			: Math.min(anchor.getY(), occupiedTopY);
		int occupiedTop = occupiedTopY;
		Graphics2D iconGraphics = (Graphics2D) graphics.create();
		try
		{
			for (NoZerosSprite icon : icons)
			{
				int canvasWidth = icon.getMaxWidth();
				int canvasHeight = icon.getMaxHeight();
				int canvasX = anchor.getX() - canvasWidth / 2;
				int canvasY = cursorBottomY - canvasHeight;
				iconGraphics.drawImage(icon.getImage(), canvasX + icon.getOffsetX(), canvasY + icon.getOffsetY(), null);
				occupiedTop = Math.min(occupiedTop, canvasY);
				cursorBottomY = canvasY;
			}
		}
		finally
		{
			iconGraphics.dispose();
		}

		return occupiedTop;
	}

	private void addPlayerIcons(List<NoZerosSprite> icons, Player player)
	{
		add(icons, plugin.getSprite(SpriteID.HEADICONS_PK, player.getSkullIcon()));

		HeadIcon prayer = player.getOverheadIcon();
		if (prayer != null)
		{
			add(icons, plugin.getSprite(SpriteID.HEADICONS_PRAYER, prayer.ordinal()));
		}
	}

	private void addNpcIcons(List<NoZerosSprite> icons, NPC npc)
	{
		int[] archiveIds = npc.getOverheadArchiveIds();
		short[] spriteIds = npc.getOverheadSpriteIds();
		if (archiveIds == null || spriteIds == null)
		{
			return;
		}

		int count = Math.min(archiveIds.length, spriteIds.length);
		for (int i = 0; i < count; i++)
		{
			int spriteId = spriteIds[i];
			if (archiveIds[i] >= 0 && spriteId >= 0)
			{
				add(icons, plugin.getSprite(archiveIds[i], spriteId));
			}
		}
	}

	private void addHintArrow(List<NoZerosSprite> icons, Actor actor)
	{
		if (!client.hasHintArrow() || client.getGameCycle() % 20 >= 10)
		{
			return;
		}

		if (actor == client.getHintArrowNpc())
		{
			add(icons, plugin.getSprite(SpriteID.HEADICONS_HINT, 0));
		}
		else if (actor == client.getHintArrowPlayer())
		{
			add(icons, plugin.getSprite(SpriteID.HEADICONS_HINT, 1));
		}
	}

	private static void add(List<NoZerosSprite> icons, NoZerosSprite icon)
	{
		if (icon != null)
		{
			icons.add(icon);
		}
	}

	private void renderHitsplats(Graphics2D graphics, Actor actor, List<NoZerosHitsplat> hitsplats, int gameCycle)
	{
		List<NoZerosHitsplat> visible = new ArrayList<>(hitsplats.size());
		for (NoZerosHitsplat hitsplat : hitsplats)
		{
			if (!hitsplat.isHidden() && hitsplat.isVisibleAt(gameCycle))
			{
				visible.add(hitsplat);
			}
		}

		if (visible.isEmpty())
		{
			return;
		}

		Point anchor = actor.getCanvasImageLocation(ANCHOR_IMAGE, actor.getLogicalHeight() / 2);
		if (anchor == null)
		{
			return;
		}

		visible.sort(RENDER_ORDER);
		List<Prepared> prepared = new ArrayList<>(visible.size());
		int slotWidth = SLOT_WIDTH;
		int slotHeight = SLOT_HEIGHT;
		for (NoZerosHitsplat hitsplat : visible)
		{
			Prepared entry = prepare(graphics, hitsplat);
			if (entry == null)
			{
				continue;
			}

			prepared.add(entry);
			slotWidth = Math.max(slotWidth, entry.layout.getWidth());
			slotHeight = Math.max(slotHeight, entry.layout.getHeight());
		}

		for (Prepared entry : prepared)
		{
			int[] offset = NoZerosLayout.slotOffset(entry.hitsplat.getPosition(), slotWidth, slotHeight, SLOT_EDGE_CUT);
			drawHitsplat(graphics, entry, anchor.getX() + offset[0], anchor.getY() + offset[1]);
		}
	}

	private Prepared prepare(Graphics2D graphics, NoZerosHitsplat hitsplat)
	{
		NoZerosHitmark definition = plugin.getDefinition(hitsplat.getType());
		if (definition == null || !definition.hasRenderableContent())
		{
			return null;
		}

		NoZerosSprite first = plugin.getSprite(definition.getFirstSpriteId(), 0);
		NoZerosSprite middle = plugin.getSprite(definition.getMiddleSpriteId(), 0);
		NoZerosSprite second = plugin.getSprite(definition.getSecondSpriteId(), 0);
		NoZerosSprite last = plugin.getSprite(definition.getLastSpriteId(), 0);

		String amountText = definition.formatAmount(hitsplat.getAmount());
		if (amountText.isEmpty() && first == null && middle == null && second == null && last == null)
		{
			return null;
		}

		NoZerosLayout layout = NoZerosLayout.create(
			first,
			middle,
			second,
			last,
			amountText,
			graphics.getFontMetrics(),
			definition.getTextYOffset());
		return new Prepared(hitsplat, definition, first, middle, second, last, amountText, layout);
	}

	private void drawHitsplat(Graphics2D graphics, Prepared prepared, int centerX, int centerY)
	{
		int spriteY = centerY + prepared.layout.getSpriteY();
		drawSprite(graphics, prepared.first, centerX + prepared.layout.getFirstX(), spriteY);
		drawSprite(graphics, prepared.second, centerX + prepared.layout.getSecondX(), spriteY);
		for (int i = 0; i < prepared.layout.getMiddleRepeatCount(); i++)
		{
			drawSprite(
				graphics,
				prepared.middle,
				centerX + prepared.layout.getMiddleX() + i * width(prepared.middle),
				spriteY);
		}
		drawSprite(graphics, prepared.last, centerX + prepared.layout.getLastX(), spriteY);

		graphics.setColor(Color.BLACK);
		graphics.drawString(
			prepared.amountText,
			centerX + prepared.layout.getTextX() + 1,
			centerY + prepared.layout.getTextBaseline() + 1);
		graphics.setColor(new Color(prepared.definition.getTextColor() | 0xFF000000, true));
		graphics.drawString(
			prepared.amountText,
			centerX + prepared.layout.getTextX(),
			centerY + prepared.layout.getTextBaseline());
	}

	private static void drawSprite(Graphics2D graphics, NoZerosSprite sprite, int x, int y)
	{
		if (sprite != null)
		{
			graphics.drawImage(sprite.getImage(), x + sprite.getOffsetX(), y + sprite.getOffsetY(), null);
		}
	}

	private static int width(NoZerosSprite sprite)
	{
		return sprite == null ? 0 : sprite.getWidth();
	}

	private static int[] healthSpritesFor(int healthScale)
	{
		for (int[] sprites : STANDARD_HEALTH_SPRITES)
		{
			if (healthScale <= sprites[0])
			{
				return sprites;
			}
		}

		return STANDARD_HEALTH_SPRITES[STANDARD_HEALTH_SPRITES.length - 1];
	}

	private static int filledWidth(int width, int ratio, int healthScale)
	{
		if (width <= 0 || ratio <= 0 || healthScale <= 0)
		{
			return 0;
		}

		return Math.max(1, width * Math.min(ratio, healthScale) / healthScale);
	}

	private static final class Prepared
	{
		private final NoZerosHitsplat hitsplat;
		private final NoZerosHitmark definition;
		private final NoZerosSprite first;
		private final NoZerosSprite middle;
		private final NoZerosSprite second;
		private final NoZerosSprite last;
		private final String amountText;
		private final NoZerosLayout layout;

		private Prepared(
			NoZerosHitsplat hitsplat,
			NoZerosHitmark definition,
			NoZerosSprite first,
			NoZerosSprite middle,
			NoZerosSprite second,
			NoZerosSprite last,
			String amountText,
			NoZerosLayout layout)
		{
			this.hitsplat = hitsplat;
			this.definition = definition;
			this.first = first;
			this.middle = middle;
			this.second = second;
			this.last = last;
			this.amountText = amountText;
			this.layout = layout;
		}
	}
}

package com.userd40.nozeros;

import com.google.inject.Provides;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.PlayerDespawned;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "No 0's",
	description = "Hides 0 damage hitsplats",
	tags = {"hitsplat", "damage", "combat", "zero"}
)
public class NoZerosPlugin extends Plugin
{
	private static final int DEFAULT_DURATION = 70;
	private static final int MAX_TRANSFORM_DEPTH = 8;

	@Inject
	private Client client;

	@Inject
	private NoZerosConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private NoZerosOverlay overlay;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	private final Map<Actor, List<NoZerosHitsplat>> hitsplats = new ConcurrentHashMap<>();
	private final Map<Integer, NoZerosHitmark> definitions = new ConcurrentHashMap<>();
	private final Map<Long, NoZerosSprite> sprites = new ConcurrentHashMap<>();
	private final RenderCallback renderCallback = new RenderCallback()
	{
		@Override
		public boolean addEntity(Renderable renderable, boolean ui)
		{
			return shouldDraw(renderable, ui);
		}
	};

	private volatile Set<Actor> suppressed = ConcurrentHashMap.newKeySet();
	private long nextSequence;

	@Provides
	NoZerosConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(NoZerosConfig.class);
	}

	@Override
	protected void startUp()
	{
		reset();
		overlayManager.add(overlay);
		renderCallbackManager.register(renderCallback);
	}

	@Override
	protected void shutDown()
	{
		renderCallbackManager.unregister(renderCallback);
		overlayManager.remove(overlay);
		reset();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			reset();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor actor = event.getActor();
		Hitsplat hitsplat = event.getHitsplat();
		if (actor == null || hitsplat == null)
		{
			return;
		}

		int amount = hitsplat.getAmount();
		boolean hidden = amount == 0 && shouldHide(actor);
		int gameCycle = client.getGameCycle();
		NoZerosHitmark definition = getDefinition(hitsplat.getHitsplatType());
		int duration = definition != null ? definition.getDuration() : DEFAULT_DURATION;
		int disappears = hitsplat.getDisappearsOnGameCycle();
		int expires = disappears > gameCycle ? disappears : gameCycle + duration;

		List<NoZerosHitsplat> actorHitsplats = hitsplats.computeIfAbsent(actor, ignored -> new CopyOnWriteArrayList<>());
		actorHitsplats.removeIf(active -> active.isExpired(gameCycle));
		int position = actorHitsplats.size();
		actorHitsplats.add(new NoZerosHitsplat(
			hitsplat.getHitsplatType(),
			amount,
			hitsplat.isMine(),
			hidden,
			position,
			gameCycle,
			expires,
			nextSequence++));
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		int gameCycle = client.getGameCycle();
		hitsplats.forEach((actor, list) -> list.removeIf(active -> active.isExpired(gameCycle)));
		hitsplats.entrySet().removeIf(entry -> entry.getValue().isEmpty());

		Set<Actor> active = ConcurrentHashMap.newKeySet();
		hitsplats.forEach((actor, list) ->
		{
			for (NoZerosHitsplat hitsplat : list)
			{
				if (hitsplat.isHidden() && hitsplat.isVisibleAt(gameCycle))
				{
					active.add(actor);
					break;
				}
			}
		});
		suppressed = active;
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		remove(event.getNpc());
	}

	@Subscribe
	public void onPlayerDespawned(PlayerDespawned event)
	{
		remove(event.getPlayer());
	}

	Map<Actor, List<NoZerosHitsplat>> getHitsplats()
	{
		return hitsplats;
	}

	boolean isSuppressed(Actor actor)
	{
		return suppressed.contains(actor);
	}

	NoZerosHitmark getDefinition(int hitsplatType)
	{
		NoZerosHitmark definition = loadDefinition(hitsplatType);
		for (int depth = 0; definition != null && depth < MAX_TRANSFORM_DEPTH; depth++)
		{
			if (!definition.hasTransforms())
			{
				return definition;
			}

			int transformedType = definition.getTransformedType(client);
			if (transformedType == NoZerosHitmark.TRANSFORM_UNAVAILABLE)
			{
				return definition;
			}
			if (transformedType < 0)
			{
				return null;
			}
			if (transformedType == hitsplatType)
			{
				return definition;
			}

			hitsplatType = transformedType;
			definition = loadDefinition(hitsplatType);
		}

		return definition;
	}

	NoZerosSprite getSprite(int archiveId, int fileId)
	{
		if (archiveId < 0 || fileId < 0)
		{
			return null;
		}

		long key = ((long) archiveId << 32) | (fileId & 0xFFFFFFFFL);
		NoZerosSprite cached = sprites.get(key);
		if (cached != null)
		{
			return cached;
		}

		NoZerosSprite loaded = NoZerosSprite.load(client, archiveId, fileId);
		if (loaded != null)
		{
			sprites.put(key, loaded);
		}
		return loaded;
	}

	private NoZerosHitmark loadDefinition(int hitsplatType)
	{
		NoZerosHitmark cached = definitions.get(hitsplatType);
		if (cached != null)
		{
			return cached;
		}

		NoZerosHitmark loaded = NoZerosHitmark.load(client, hitsplatType);
		if (loaded != null && !loaded.isFallbackDefinition())
		{
			definitions.put(hitsplatType, loaded);
		}
		return loaded;
	}

	private boolean shouldHide(Actor actor)
	{
		if (actor instanceof NPC)
		{
			return config.hideNpc();
		}
		if (actor == client.getLocalPlayer())
		{
			return config.hidePlayer();
		}
		if (actor instanceof Player)
		{
			return config.hideOtherPlayer();
		}
		return false;
	}

	private boolean shouldDraw(Renderable renderable, boolean drawingUI)
	{
		return !(drawingUI && renderable instanceof Actor && suppressed.contains(renderable));
	}

	private void remove(Actor actor)
	{
		hitsplats.remove(actor);
		suppressed.remove(actor);
	}

	private void reset()
	{
		hitsplats.clear();
		suppressed = ConcurrentHashMap.newKeySet();
		nextSequence = 0;
	}
}

package com.userd40.nozeros;

import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.SpritePixels;

final class NoZerosSprite
{
	private final BufferedImage image;
	private final int width;
	private final int height;
	private final int maxWidth;
	private final int maxHeight;
	private final int offsetX;
	private final int offsetY;

	private NoZerosSprite(BufferedImage image, int maxWidth, int maxHeight, int offsetX, int offsetY)
	{
		this.image = image;
		this.width = image.getWidth();
		this.height = image.getHeight();
		this.maxWidth = Math.max(this.width, maxWidth);
		this.maxHeight = Math.max(this.height, maxHeight);
		this.offsetX = offsetX;
		this.offsetY = offsetY;
	}

	static NoZerosSprite load(Client client, int spriteId)
	{
		return load(client, spriteId, 0);
	}

	static NoZerosSprite load(Client client, int archiveId, int fileId)
	{
		if (archiveId < 0 || fileId < 0)
		{
			return null;
		}

		try
		{
			SpritePixels[] sprites = client.getSprites(client.getIndexSprites(), archiveId, 0);
			if (sprites == null || fileId >= sprites.length || sprites[fileId] == null)
			{
				return null;
			}

			SpritePixels sprite = sprites[fileId];
			BufferedImage image = sprite.toBufferedImage();
			if (image == null)
			{
				return null;
			}

			return new NoZerosSprite(image, sprite.getMaxWidth(), sprite.getMaxHeight(), sprite.getOffsetX(), sprite.getOffsetY());
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	BufferedImage getImage()
	{
		return image;
	}

	int getWidth()
	{
		return width;
	}

	int getHeight()
	{
		return height;
	}

	int getMaxWidth()
	{
		return maxWidth;
	}

	int getMaxHeight()
	{
		return maxHeight;
	}

	int getOffsetX()
	{
		return offsetX;
	}

	int getOffsetY()
	{
		return offsetY;
	}
}

